## MSTest Comparison Assertions

MSTest 3.x+ provides these comparison assertions (no `Assert.IsTrue` needed):

```csharp
Assert.IsGreaterThan(lowerBound, actual);   // actual > lowerBound
Assert.IsLessThan(upperBound, actual);      // actual < upperBound
Assert.IsInRange(actual, low, high);        // low <= actual <= high
```

Here's a test class for your `ScoreCalculator`:

```csharp
[TestClass]
public sealed class ScoreCalculatorTests
{
    private readonly ScoreCalculator _calculator = new();

    [TestMethod]
    [DataRow(7, 10, 70.0)]
    [DataRow(10, 10, 100.0)]
    [DataRow(0, 10, 0.0)]
    public void CalculatePercentage_ValidInputs_ReturnsExpected(int correct, int total, double expected)
    {
        var result = _calculator.CalculatePercentage(correct, total);
        Assert.AreEqual(expected, result);
    }

    [TestMethod]
    public void CalculatePercentage_CorrectExceedsTotal_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculatePercentage(11, 10));
    }

    [TestMethod]
    public void CalculatePercentage_ZeroTotal_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculatePercentage(0, 0));
    }

    [TestMethod]
    [DataRow(90.0, "A")]
    [DataRow(89.9, "B")]
    [DataRow(80.0, "B")]
    [DataRow(70.0, "C")]
    [DataRow(60.0, "D")]
    [DataRow(59.9, "F")]
    public void GetGrade_AtBoundary_ReturnsCorrectGrade(double percentage, string expected)
    {
        Assert.AreEqual(expected, _calculator.GetGrade(percentage));
    }

    [TestMethod]
    public void NormalizeScore_ValidInput_ReturnsInRange()
    {
        var result = _calculator.NormalizeScore(75, 150);

        Assert.IsInRange(result, 0.0, 100.0);
        Assert.AreEqual(50.0, result);
    }

    [TestMethod]
    public void NormalizeScore_ExceedsMax_CapsAt100()
    {
        var result = _calculator.NormalizeScore(200, 100);

        Assert.AreEqual(100.0, result);
        Assert.IsLessThan(101.0, result); // never exceeds 100
    }

    [TestMethod]
    public void NormalizeScore_NegativeRawScore_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.NormalizeScore(-1, 100));
    }

    [TestMethod]
    public void CalculatePercentage_PartialScore_ResultIsGreaterThanZero()
    {
        var result = _calculator.CalculatePercentage(1, 10);

        Assert.IsGreaterThan(0.0, result);
        Assert.IsLessThan(100.0, result);
    }
}
```

**Key points:**
- `Assert.IsInRange(actual, low, high)` — perfect for verifying normalized scores stay within bounds
- `Assert.IsGreaterThan(lowerBound, actual)` / `Assert.IsLessThan(upperBound, actual)` — for one-sided boundary checks
- Use `[DataRow]` at grade boundaries (90, 80, 70, 60) and just below (89.9, etc.) to test the `switch` edges
- Use `Assert.ThrowsExactly<T>` for invalid input paths instead of `[ExpectedException]`
